def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my = [h[0] for h in history]
    op = [h[1] for h in history]
    my_last = my[-1]
    op_last = op[-1]

    opp_d = sum(1 for a in op if a == 'D')
    my_d = sum(1 for a in my if a == 'D')

    soft = 0
    hard = 0
    for i in range(n - 1):
        if my[i] == 'D':
            if op[i + 1] == 'D':
                hard += 1
            else:
                soft += 1

    start = n - 10
    if start < 0:
        start = 0
    recent_op = op[start:]
    recent_op_d = sum(1 for a in recent_op if a == 'D')

    if op_last == 'D':
        if my_last == 'D':
            if recent_op_d >= 4 or opp_d * 2 > n:
                return 'D'
            return 'C'
        if recent_op_d >= 2 or opp_d * 2 > n:
            return 'D'
        if hard > 0:
            return 'C'
        if n >= 5 and recent_op_d <= 1 and opp_d <= max(1, n // 10):
            return 'C'
        return 'D'

    if recent_op_d >= 4 or opp_d * 2 > n:
        return 'D'

    if hard == 0 and soft >= 1:
        if recent_op_d <= max(1, n // 10):
            return 'D'

    if my_d == 0 and hard == 0 and soft == 0 and recent_op_d == 0 and n >= 80:
        return 'D'

    if my_d == 0 and hard == 0 and soft == 0 and n >= 90 and recent_op_d <= max(1, n // 10):
        return 'D'

    if my_last == 'D' and op_last == 'C' and soft == 0 and hard == 0:
        return 'C'

    return 'C'
